/* gemm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* ---------------------------------------------------------------------
 * Tunable blocking parameters.
 *
 * These control the tile sizes used in the blocked GEMM implementation
 * below.  They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DGEMM_BLOCK_I=128 -DGEMM_BLOCK_J=128 -DGEMM_BLOCK_K=32 ...
 *
 * The defaults are conservative and should work well on typical
 * modern x86-64 cores with 32 KB L1 and ~1 MB L2 caches.
 * -------------------------------------------------------------------*/
#ifndef GEMM_BLOCK_I
# define GEMM_BLOCK_I 64
#endif

#ifndef GEMM_BLOCK_J
# define GEMM_BLOCK_J 64
#endif

#ifndef GEMM_BLOCK_K
# define GEMM_BLOCK_K 32
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void __attribute__((noinline, flatten))
kernel_gemm(int ni, int nj, int nk,
	     DATA_TYPE alpha,
	     DATA_TYPE beta,
	     DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
	     DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
	     DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

  /* Create local restrict-qualified aliases for the input matrices.
   * This tells the compiler that A, B, and C do not alias each other,
   * which enables more aggressive vectorization and reordering.
   *
   * The dimensions (nj, nk) are taken from the function parameters,
   * so these are VLAs but still contiguous in memory.
   */
  DATA_TYPE (*restrict C_)[nj] = C;
  DATA_TYPE (*restrict A_)[nk] = A;
  DATA_TYPE (*restrict B_)[nj] = B;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* First scale C by beta:
   *    C[i][j] <- beta * C[i][j]
   *
   * Doing this as a separate pass keeps the main GEMM kernel simpler
   * and ensures a single, easily vectorizable streaming access over C.
   * For each element (i,j), the sequence:
   *   C[i][j] = beta*C[i][j];
   *   C[i][j] += alpha * sum_k A[i][k]*B[k][j];
   * is preserved, so the per-element computation is unchanged.
   */
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *restrict c_row = &C_[i][0];
    for (j = 0; j < _PB_NJ; j++) {
      c_row[j] *= beta;
    }
  }

  /* Blocked matrix multiplication:
   *
   * C[i][j] += alpha * A[i][k] * B[k][j]
   *
   * Loop order and blocking are chosen to:
   *   - keep the innermost loop over j so that accesses to
   *     C[i][j] and B[k][j] are stride-1 (contiguous in memory);
   *   - reuse blocks of B and A from cache across multiple rows of C;
   *   - preserve the original accumulation order in k for each (i,j).
   *
   * The blocking factors GEMM_BLOCK_{I,J,K} are tunable.
   * For each fixed (i, j), we visit k in strictly increasing order
   * (0 .. nk-1) exactly once, just as in the original kernel,
   * so floating-point reduction order per element is preserved.
   */
  const int Ti = GEMM_BLOCK_I;
  const int Tj = GEMM_BLOCK_J;
  const int Tk = GEMM_BLOCK_K;

  for (int ii = 0; ii < _PB_NI; ii += Ti) {
    const int i_end = (ii + Ti < _PB_NI) ? (ii + Ti) : _PB_NI;

    for (int kk = 0; kk < _PB_NK; kk += Tk) {
      const int k_end = (kk + Tk < _PB_NK) ? (kk + Tk) : _PB_NK;

      for (int jj = 0; jj < _PB_NJ; jj += Tj) {
        const int j_end = (jj + Tj < _PB_NJ) ? (jj + Tj) : _PB_NJ;

        for (i = ii; i < i_end; i++) {
          for (k = kk; k < k_end; k++) {
            /* alpha * A[i][k] is reused across the inner j-loop. */
            const DATA_TYPE a_ik = alpha * A_[i][k];

            /* Row pointers to avoid repeated address arithmetic.
             * For this fixed (i, k) pair we walk linearly across j.
             */
            DATA_TYPE *restrict       c_ptr = &C_[i][jj];
            const DATA_TYPE *restrict b_ptr = &B_[k][jj];

            /* Innermost loop: stride-1 access for both C and B. */
            #pragma GCC ivdep
            for (j = jj; j < j_end; j++) {
              *c_ptr += a_ik * (*b_ptr);
              ++c_ptr;
              ++b_ptr;
            }
          }
        }
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
