#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* --------------------------------------------------------------------
 * Tunable blocking parameters for the GEMM kernel.
 *
 * These control the cache tiling/blocking sizes along the I, J and K
 * dimensions. They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DGEMM_TILE_I=128 -DGEMM_TILE_J=128 -DGEMM_TILE_K=32 ...
 *
 * to better match a specific machine's cache hierarchy.
 * ------------------------------------------------------------------ */
#ifndef GEMM_TILE_I
# define GEMM_TILE_I 64
#endif

#ifndef GEMM_TILE_J
# define GEMM_TILE_J 64
#endif

#ifndef GEMM_TILE_K
# define GEMM_TILE_K 64
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* C initialization: row-major, contiguous accesses along j. */
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;

  /* A initialization: row-major, contiguous accesses along j. */
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;

  /* B initialization: row-major, contiguous accesses along j. */
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Parameters are kept for interface compatibility; PolyBench uses
   * the _PB_* macros for loop bounds. */
  (void)ni;
  (void)nj;
  (void)nk;

  int i, j, k;
  int ii, jj, kk;

  /* Local restrict-qualified aliases for better optimization.
   *
   * PolyBench allocates A, B, and C as distinct, aligned buffers, so
   * it is safe to tell the compiler they do not alias. This allows
   * more aggressive vectorization and reordering while preserving
   * the intended semantics.
   */
  DATA_TYPE (*restrict C_)[NJ] = (DATA_TYPE (*restrict)[NJ]) C;
  DATA_TYPE (*restrict A_)[NK] = (DATA_TYPE (*restrict)[NK]) A;
  DATA_TYPE (*restrict B_)[NJ] = (DATA_TYPE (*restrict)[NJ]) B;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* ------------------------------------------------------------------
   * Step 1: Scale C by beta.
   *
   * This is kept as a separate pass but written to favor unit-stride
   * accesses along the inner loop (j), which is optimal for cache and
   * vectorization.
   * ---------------------------------------------------------------- */
  for (i = 0; i < _PB_NI; ++i) {
    DATA_TYPE *restrict Ci = C_[i];
    for (j = 0; j < _PB_NJ; ++j) {
      Ci[j] *= beta;
    }
  }

  /* ------------------------------------------------------------------
   * Step 2: Tiled GEMM update:
   *   C[i][j] += alpha * A[i][k] * B[k][j]
   *
   * Blocking over K, then I, then J improves data locality:
   *  - Each block of B[k][:] is reused across a block of rows of A/C.
   *  - Inner-most loop walks contiguous regions of C and B to enable
   *    efficient SIMD vectorization.
   *
   * The order of accumulation over k for each C[i][j] remains 0..NK-1,
   * exactly as in the original code, so floating-point round-off
   * behavior is preserved. The product alpha*A[i][k] is computed once
   * per (i,k) pair (it was recomputed per (i,k,j) previously), which
   * is mathematically equivalent because the operands are identical.
   * ---------------------------------------------------------------- */
  for (kk = 0; kk < _PB_NK; kk += GEMM_TILE_K) {
    int kend = kk + GEMM_TILE_K;
    if (kend > _PB_NK)
      kend = _PB_NK;

    for (ii = 0; ii < _PB_NI; ii += GEMM_TILE_I) {
      int iend = ii + GEMM_TILE_I;
      if (iend > _PB_NI)
        iend = _PB_NI;

      for (jj = 0; jj < _PB_NJ; jj += GEMM_TILE_J) {
        int jend = jj + GEMM_TILE_J;
        if (jend > _PB_NJ)
          jend = _PB_NJ;

        const int tlen = jend - jj; /* length of the J-tile */

        for (k = kk; k < kend; ++k) {
          /* Row k of B, restricted to the current J-tile. */
          DATA_TYPE *restrict Bk = &B_[k][jj];

          for (i = ii; i < iend; ++i) {
            /* alpha * A[i][k] is invariant across the inner j-loop. */
            const DATA_TYPE a_ik = alpha * A_[i][k];

            /* Row i of C, restricted to the current J-tile. */
            DATA_TYPE *restrict Ci = &C_[i][jj];

            /* Innermost loop: unit-stride over the tile in J.
             * Marked with ivdep to help the compiler ignore any
             * spurious dependencies and fully vectorize.
             */
#pragma GCC ivdep
            for (j = 0; j < tlen; ++j) {
              Ci[j] += a_ik * Bk[j];
            }
          }
        }
      }
    }
  }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
