/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

  /* Create local restrict-qualified views of the matrices.
   *
   * This improves the compiler's alias analysis: C_, A_ and B_ are
   * guaranteed not to alias each other, which enables more aggressive
   * hoisting, vectorization and use of FMA instructions.
   */
  DATA_TYPE       (* restrict C_)[nj] = (DATA_TYPE       (* restrict)[nj]) C;
  const DATA_TYPE (* restrict A_)[nk] = (const DATA_TYPE (* restrict)[nk]) A;
  const DATA_TYPE (* restrict B_)[nj] = (const DATA_TYPE (* restrict)[nj]) B;

  /* Use the PolyBench loop bounds (they may differ from ni/nj/nk when
   * using the PolyBench support for reduced-size runs). */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

#pragma scop
  /* ------------------------------------------------------------------
   * Step 1: Scale C by beta.
   *
   * This is algebraically equivalent to the original code, which
   * performed the scaling row-by-row immediately before the GEMM
   * accumulation for that row:
   *   C = beta * C + alpha * A * B
   * ------------------------------------------------------------------ */
  for (i = 0; i < ni_; i++) {
    DATA_TYPE * restrict Ci = C_[i];
#pragma GCC ivdep
    for (j = 0; j < nj_; j++) {
      Ci[j] *= beta_;
    }
  }

  /* ------------------------------------------------------------------
   * Step 2: Blocked matrix multiplication:
   *   C += alpha * A * B
   *
   * We use a 3D blocking strategy over i, j, k to increase cache
   * locality. The block sizes GEMM_TILE_{I,J,K} are tunable via
   * preprocessor macros.
   *
   * Loop order within a block:
   *   for (i in i-block)
   *     for (k in k-block)
   *       for (j in j-block)
   *
   * - A_[i][k] is accessed with k as the inner index (good spatial
   *   locality in A’s rows).
   * - B_[k][j] and C_[i][j] are accessed with j as the inner index
   *   (contiguous memory, good for vectorization).
   * ------------------------------------------------------------------ */
  for (int ii = 0; ii < ni_; ii += GEMM_TILE_I) {
    const int i_max = (ii + GEMM_TILE_I < ni_) ? (ii + GEMM_TILE_I) : ni_;

    for (int kk = 0; kk < nk_; kk += GEMM_TILE_K) {
      const int k_max = (kk + GEMM_TILE_K < nk_) ? (kk + GEMM_TILE_K) : nk_;

      for (int jj = 0; jj < nj_; jj += GEMM_TILE_J) {
        const int j_max = (jj + GEMM_TILE_J < nj_) ? (jj + GEMM_TILE_J) : nj_;
        const int width = j_max - jj;

        for (i = ii; i < i_max; i++) {
          /* Pointer to the beginning of the current C sub-row. */
          DATA_TYPE * restrict Ci_block = &C_[i][jj];

          for (k = kk; k < k_max; k++) {
            const DATA_TYPE a_ik = alpha_ * A_[i][k];
            const DATA_TYPE * restrict Bk_block = &B_[k][jj];

            /* Innermost loop works on contiguous elements of C and B.
             * GCC is explicitly told that there are no loop-carried
             * dependencies via ivdep so it can safely vectorize. */
#pragma GCC ivdep
            for (j = 0; j < width; j++) {
              Ci_block[j] += a_ik * Bk_block[j];
            }
          }
        }
      }
    }
  }
#pragma endscop
}


