static
void kernel_gemm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Use local restrict-qualified VLA pointers.
   *
   * This tells the compiler that:
   *   - A, B, and C do not alias each other.
   *   - Rows are contiguous in memory (row-major layout).
   *
   * That greatly helps vectorization and cache-aware optimizations,
   * while preserving the original observable behavior (the PolyBench
   * driver always passes distinct arrays).
