  DATA_TYPE       (*restrict C_)[nj] = (DATA_TYPE       (*)[nj]) C;
  const DATA_TYPE (*restrict A_)[nk] = (const DATA_TYPE (*)[nk]) A;
  const DATA_TYPE (*restrict B_)[nj] = (const DATA_TYPE (*)[nj]) B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  int i, j, k;
  int ii, jj, kk;

  /* Tunable blocking parameters (runtime copies of the macros). */
  const int bi = GEMM_BLOCK_I;
  const int bj = GEMM_BLOCK_J;
  const int bk = GEMM_BLOCK_K;

