  /* ------------------------------------------------------------------ */
  /* 1) Scale C by beta                                                 */
  /* ------------------------------------------------------------------ */
  /* This loop is mathematically:
   *   for i in [0,NI)
   *     for j in [0,NJ)
   *       C[i][j] *= beta;
   *
   * We keep the per-element evaluation order identical but apply
   * cache-friendly blocking over i and j.
   */
  for (ii = 0; ii < _PB_NI; ii += bi) {
    int i_end = ii + bi;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (jj = 0; jj < _PB_NJ; jj += bj) {
      int j_end = jj + bj;
      if (j_end > _PB_NJ)
        j_end = _PB_NJ;

      for (i = ii; i < i_end; ++i) {
        DATA_TYPE *restrict C_row = &C_[i][0];

        /* Inner loop has unit stride; easy to vectorize. */
        for (j = jj; j < j_end; ++j) {
